def find_path(graph, start, goal):
    open_set = set([start])
    closed_set = set()
    parent = {}
    path = []
    found = False
    while not found and open_set:
        current = None
        for node in open_set:
            if current is None or len(graph[node]) > len(graph[current]):
                current = node
        if current == goal:
            found = True
            path.append(goal)
            while current in parent:
                path.append(current)
                current = parent[current]
            path.append(current)
            path.reverse()
            return path
        open_set.remove(current)
        closed_set.add(current)
        for child in graph[current]:
            if child not in closed_set:
                parent[child] = current
                open_set.add(child)
    return None
